"""One-shot root adjudication of six differing blind boxes on scan 051."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];p='149_scan051';rp=R/'records'/f'{p}.json';r=json.loads(rp.read_text());pp=R/'pages'/f'{p}.tex';s=pp.read_text();cmp={x['box']:x for x in json.loads((R/'second'/f'{p}_comparison.json').read_text())};f={b:x['first'] for b,x in cmp.items()}
