for d in r['doubts']:
    if 'M1127' in d['place']:d.update(reading=sign,alternatives='literal q-like glyph first; cancelled d; cancelled f; universal sign',reason='The rounded bowl and long descent favour q, while the upper extension and dark retracing leave both letter identity and cancellation state open. The entire surrounding expression was reread.')
    if 'cancelled word after en' in d['place']:d.update(reading=r'\deleted{\unsure{égale|égalant}}',alternatives='égale | égalant',reason='The e/g/l skeleton is visible; the strike hides the final low courses, which could extend to ant.')
